-- ============================================================================
-- B5 FOLLOW-ON W2 (publish inputs in prompts and lessons): nodal.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 1,
-- route (a), and the spec docs/graded-field-audit/w2/nodal.json (the
-- inputs, where each came from, and the key each reproduces through the
-- vendored engines). Owner approved D1 to D7 as recommended, 2026-09-21.
--
-- INTERMEDIATE
--   Prompt only, no field moves. The prompt called the tubing curve "the
--   gravity-plus-friction relation supplied with this capstone" and never stated
--   its constants (3835, 600, 0.000238 lived only in nodalLab.js CAP), nor where
--   the 49 points start (B5 finding 1). The prompt now states the relation, the
--   wellhead pressure and the sampling, and restates the inflow the open flow
--   comes from, so the four tubing fields are spreadsheet work on a form the
--   course teaches (intermediate m03 l03). The two lift gas fields still need a
--   Cullender and Smith march with the engine z; they stay class display for the
--   W4 panel mode.
--   PROMPT was: The tubing curve is the gravity-plus-friction relation supplied
--   with this capstone, evaluated at a wellhead pressure of 1,236 psia over 49
--   points from just above zero to the absolute open flow.
--   PROMPT now: The tubing curve is the gravity-plus-friction relation bhp(q) =
--   pWh + 3835 / (1 + q/600) + 0.000238 q^2, with bhp and pWh in psia and q in
--   stb/d, evaluated at a wellhead pressure of 1236 psia at 49 evenly spaced
--   rates from one thousandth of the absolute open flow up to the absolute open
--   flow itself. The open flow is the Associate tier's, from its composite
--   inflow: reservoir pressure 3450 psia, bubble point 3100 psia and one test of
--   1200 stb/d at 2790 psia.
--
-- ADVANCED
--   Prompt only, no field moves. The node needs the tubing relation, which no
--   prompt stated, and the grid needed its span: the prompt now states the
--   Associate inflow, the Professional outflow with its constants, and that the
--   900 points only bracket each crossing, which is then solved exactly. Every
--   field is then a spreadsheet root find (verified: the roots match the key to
--   about 1e-6 stb/d).
--   PROMPT was: Solve on a 900-point grid.
--   PROMPT now: The inflow is the Associate tier's composite relation (reservoir
--   pressure 3450 psia, bubble point 3100 psia and one test of 1200 stb/d at
--   2790 psia) and the outflow is the Professional tier's tubing relation bhp(q)
--   = pWh + 3835 / (1 + q/600) + 0.000238 q^2 psia at a wellhead pressure of
--   1236 psia. Solve on a 900-point grid of rates evenly spaced from one
--   thousandth to 0.999 of the absolute open flow: the grid only brackets each
--   crossing, and a crossing is the exact rate at which the two pressures agree,
--   with its flowing pressure read off the inflow.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected value and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its live value exactly, before and after, so no answer grades
-- differently, nobody is re-scored and no attempts guard is needed.
--
-- GUARDS. Each row must hold EITHER its published prompt (by md5) with its
-- live fields (exact jsonb), as production holds it after W1 (it is
-- rewritten), OR its W2 prompt with the same fields (left alone). Anything
-- else raises and the whole file rolls back. A file that will write first
-- checks the W1 post-state and refuses without it. Generated by
-- docs/graded-field-audit/w2_capstones.py. SAFE TO RE-RUN: a second run
-- writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
  v_s1       text;
begin
  -- nodal / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'nodal' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w2 nodal refused: nodal/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'b22f2f25e9f3c371a3caae8ccbbd4621' and fields = '[{"key": "vlp_min_q_stbd", "tol": 0.00064, "unit": "stb/d", "label": "Rate at the curve minimum", "expected": 1285.2338376891341}, {"key": "vlp_min_bhp_psia", "tol": 0.0014, "unit": "psia", "label": "Pressure at the minimum", "expected": 2849.67283735105}, {"key": "vlp_loaded_end_bhp_psia", "tol": 0.0025, "unit": "psia", "label": "Low rate end", "expected": 5046.565087663264}, {"key": "vlp_friction_end_bhp_psia", "tol": 0.0026, "unit": "psia", "label": "Open flow end", "expected": 5277.411341029544}, {"key": "liftgas_valve_pwf_psia", "tol": 0.00076, "unit": "psia", "label": "Injection pressure at depth", "expected": 1516.5314295864096}, {"key": "liftgas_mid_pmf_psia", "tol": 0.00069, "unit": "psia", "label": "Injection pressure at midpoint", "expected": 1373.724371881081}]'::jsonb then 'old'
              when md5(prompt) = '43e9b4136348adc42dd5053de84d8367' and fields = '[{"key": "vlp_min_q_stbd", "tol": 0.00064, "unit": "stb/d", "label": "Rate at the curve minimum", "expected": 1285.2338376891341}, {"key": "vlp_min_bhp_psia", "tol": 0.0014, "unit": "psia", "label": "Pressure at the minimum", "expected": 2849.67283735105}, {"key": "vlp_loaded_end_bhp_psia", "tol": 0.0025, "unit": "psia", "label": "Low rate end", "expected": 5046.565087663264}, {"key": "vlp_friction_end_bhp_psia", "tol": 0.0026, "unit": "psia", "label": "Open flow end", "expected": 5277.411341029544}, {"key": "liftgas_valve_pwf_psia", "tol": 0.00076, "unit": "psia", "label": "Injection pressure at depth", "expected": 1516.5314295864096}, {"key": "liftgas_mid_pmf_psia", "tol": 0.00069, "unit": "psia", "label": "Injection pressure at midpoint", "expected": 1373.724371881081}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'nodal' and tier = 'intermediate' and active;
  if v_s0 = 'other' then
    raise exception 'w2 nodal refused: nodal/intermediate matches neither its published form (prompt md5 b22f2f25e9f3c371a3caae8ccbbd4621) nor its W2 form (prompt md5 43e9b4136348adc42dd5053de84d8367), with the fields this file was generated against';
  end if;

  -- nodal / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'nodal' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w2 nodal refused: nodal/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'fa1e57c1002c5732351b93fd8f864585' and fields = '[{"key": "node_op_q_stbd", "tol": 0.00046, "unit": "stb/d", "label": "Operating rate", "expected": 929.9820637311327}, {"key": "node_op_pwf_psia", "tol": 0.0015, "unit": "psia", "label": "Operating pressure", "expected": 2945.7774594005996}, {"key": "node_unstable_q_stbd", "tol": 0.00045, "unit": "stb/d", "label": "Unstable crossing rate", "expected": 905.3367675852949}, {"key": "node_unstable_pwf_psia", "tol": 0.0015, "unit": "psia", "label": "Unstable crossing pressure", "expected": 2959.6346643478146}, {"key": "sweep_pwh1176_q_stbd", "tol": 0.00057, "unit": "stb/d", "label": "Rate at 1176 psia wellhead", "expected": 1184.0068509231141}, {"key": "sweep_pwh1176_pwf_psia", "tol": 0.0015, "unit": "psia", "label": "Pressure at 1176 psia wellhead", "expected": 2799.4388422395805}]'::jsonb then 'old'
              when md5(prompt) = 'e0c4b42254be64aaca38fba15d011657' and fields = '[{"key": "node_op_q_stbd", "tol": 0.00046, "unit": "stb/d", "label": "Operating rate", "expected": 929.9820637311327}, {"key": "node_op_pwf_psia", "tol": 0.0015, "unit": "psia", "label": "Operating pressure", "expected": 2945.7774594005996}, {"key": "node_unstable_q_stbd", "tol": 0.00045, "unit": "stb/d", "label": "Unstable crossing rate", "expected": 905.3367675852949}, {"key": "node_unstable_pwf_psia", "tol": 0.0015, "unit": "psia", "label": "Unstable crossing pressure", "expected": 2959.6346643478146}, {"key": "sweep_pwh1176_q_stbd", "tol": 0.00057, "unit": "stb/d", "label": "Rate at 1176 psia wellhead", "expected": 1184.0068509231141}, {"key": "sweep_pwh1176_pwf_psia", "tol": 0.0015, "unit": "psia", "label": "Pressure at 1176 psia wellhead", "expected": 2799.4388422395805}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'nodal' and tier = 'advanced' and active;
  if v_s1 = 'other' then
    raise exception 'w2 nodal refused: nodal/advanced matches neither its published form (prompt md5 fa1e57c1002c5732351b93fd8f864585) nor its W2 form (prompt md5 e0c4b42254be64aaca38fba15d011657), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W2 form
  if v_s0 = 'new' and v_s1 = 'new' then
    raise notice 'w2 nodal: 0 of 2 row(s) written, all already applied';
    return;
  end if;

  -- W1 (20261024a/b) must be applied first: production holds it, and the W2
  -- apply script checks all 34 files; this reads two of its rows
  if exists (select 1 from public.academy_capstones where app_slug = 'integrity' and tier = 'beginner' and active and md5(prompt) <> '0e0ac66d6b97e9f7f66b5055e1fddf7d')
     or exists (select 1 from public.academy_capstones where app_slug = 'welldata' and tier = 'beginner' and active and md5(prompt) <> 'f362ed27e7d8766e7e51dcf1ca0e5e6e') then
    raise exception 'w2 nodal refused: W1 (20261024*) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Six values for the NEMBE-14 outflow, built on the open flow the Associate tier established. The tubing curve is the gravity-plus-friction relation bhp(q) = pWh + 3835 / (1 + q/600) + 0.000238 q^2, with bhp and pWh in psia and q in stb/d, evaluated at a wellhead pressure of 1236 psia at 49 evenly spaced rates from one thousandth of the absolute open flow up to the absolute open flow itself. The open flow is the Associate tier''s, from its composite inflow: reservoir pressure 3450 psia, bubble point 3100 psia and one test of 1200 stb/d at 2790 psia. The gas-lift injection column is a dry gas column of specific gravity 0.72 at 1,225 psia at the tubing head, 8,900 ft measured and 8,300 ft true vertical, from 96 degF to 214 degF, marched in 20 steps. Report: (1) the RATE at the MINIMUM of the tubing curve; (2) the bottomhole pressure AT that minimum; (3) the bottomhole pressure at the LOW RATE end of the curve; (4) the bottomhole pressure at the OPEN FLOW end; (5) the injection-gas pressure at the VALVE depth; and (6) the injection-gas pressure at the MIDPOINT of the column. Traps. Fields 3 and 4 are the two ENDS of the same curve and both must come out ABOVE the reservoir pressure of 3,450 psia, which is the whole point of this well: the column outweighs the reservoir at both ends and the well cannot start itself. A learner who reports a low-rate end below reservoir pressure has evaluated the gravity term at the wrong place. Field 1 is read off the SAMPLED curve at the stated 49 points and not off an analytic minimum, because the sampled minimum is what the engine returns and a finer sampling moves it. The injection column is marched at TWENTY steps and not at the published two-station default; on a gravity-only column the two answers differ by only a fraction of a psi, which is exactly why the difference is easy to miss and why the tier makes you state the step count. Free checks: field 2 must be the smallest bottomhole pressure anywhere on the curve, and both fields 3 and 4 must exceed it; field 1 must fall strictly between the ends of the rate range; and field 6 must sit between the 1,225 psia tubing head pressure and field 5, since a static gas column only gains pressure with depth.'
     where app_slug = 'nodal' and tier = 'intermediate' and active and md5(prompt) = 'b22f2f25e9f3c371a3caae8ccbbd4621';
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w2 nodal refused: nodal/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '43e9b4136348adc42dd5053de84d8367' and fields = '[{"key": "vlp_min_q_stbd", "tol": 0.00064, "unit": "stb/d", "label": "Rate at the curve minimum", "expected": 1285.2338376891341}, {"key": "vlp_min_bhp_psia", "tol": 0.0014, "unit": "psia", "label": "Pressure at the minimum", "expected": 2849.67283735105}, {"key": "vlp_loaded_end_bhp_psia", "tol": 0.0025, "unit": "psia", "label": "Low rate end", "expected": 5046.565087663264}, {"key": "vlp_friction_end_bhp_psia", "tol": 0.0026, "unit": "psia", "label": "Open flow end", "expected": 5277.411341029544}, {"key": "liftgas_valve_pwf_psia", "tol": 0.00076, "unit": "psia", "label": "Injection pressure at depth", "expected": 1516.5314295864096}, {"key": "liftgas_mid_pmf_psia", "tol": 0.00069, "unit": "psia", "label": "Injection pressure at midpoint", "expected": 1373.724371881081}]'::jsonb) from public.academy_capstones where app_slug = 'nodal' and tier = 'intermediate' and active) is not true then
    raise exception 'w2 nodal refused: nodal/intermediate does not read back as its W2 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Six values for NEMBE-14, solving the node where the Associate tier''s inflow meets the Professional tier''s outflow. The inflow is the Associate tier''s composite relation (reservoir pressure 3450 psia, bubble point 3100 psia and one test of 1200 stb/d at 2790 psia) and the outflow is the Professional tier''s tubing relation bhp(q) = pWh + 3835 / (1 + q/600) + 0.000238 q^2 psia at a wellhead pressure of 1236 psia. Solve on a 900-point grid of rates evenly spaced from one thousandth to 0.999 of the absolute open flow: the grid only brackets each crossing, and a crossing is the exact rate at which the two pressures agree, with its flowing pressure read off the inflow. Report: (1) the OPERATING rate; (2) the flowing pressure at the operating point; (3) the rate at the UNSTABLE crossing; (4) the flowing pressure there; and then, sweeping the wellhead pressure, (5) the operating rate and (6) the flowing pressure at a wellhead pressure of 1,176 psia. Traps. This node has TWO crossings and the difference between them is the whole tier: the LOWER rate one is the heading branch, where a well is driven away from the crossing by any disturbance, and the HIGHER rate one is where the well actually produces. Reporting the first intersection a solver hands back swaps fields 1 and 2 with fields 3 and 4. The grid is stated at 900 points and that is not decoration: at the solver''s default of 40 the two crossings fall inside a single interval, the residual never changes sign, and the engine reports this live well DEAD. Raising the grid is not monotone in that verdict either, so trying a middling count and getting a dead well a second time is not evidence the well is dead. Field 5 is not a small correction to field 1. Free checks: field 1 must exceed field 3 and field 2 must be BELOW field 4, since the outflow is falling across the window; the two crossings must sit less than 30 stb/d apart on a well whose open flow is nearly 3,850 stb/d; field 2 must come out ABOVE the minimum of the tubing curve the Professional tier reported, because this well holds on the FALLING limb and not at the bottom of it; and field 5 must exceed field 1 by more than 250 stb/d, because a 60 psi reduction at the wellhead near tangency buys far more than 60 psi of drawdown would suggest.'
     where app_slug = 'nodal' and tier = 'advanced' and active and md5(prompt) = 'fa1e57c1002c5732351b93fd8f864585';
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w2 nodal refused: nodal/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'e0c4b42254be64aaca38fba15d011657' and fields = '[{"key": "node_op_q_stbd", "tol": 0.00046, "unit": "stb/d", "label": "Operating rate", "expected": 929.9820637311327}, {"key": "node_op_pwf_psia", "tol": 0.0015, "unit": "psia", "label": "Operating pressure", "expected": 2945.7774594005996}, {"key": "node_unstable_q_stbd", "tol": 0.00045, "unit": "stb/d", "label": "Unstable crossing rate", "expected": 905.3367675852949}, {"key": "node_unstable_pwf_psia", "tol": 0.0015, "unit": "psia", "label": "Unstable crossing pressure", "expected": 2959.6346643478146}, {"key": "sweep_pwh1176_q_stbd", "tol": 0.00057, "unit": "stb/d", "label": "Rate at 1176 psia wellhead", "expected": 1184.0068509231141}, {"key": "sweep_pwh1176_pwf_psia", "tol": 0.0015, "unit": "psia", "label": "Pressure at 1176 psia wellhead", "expected": 2799.4388422395805}]'::jsonb) from public.academy_capstones where app_slug = 'nodal' and tier = 'advanced' and active) is not true then
    raise exception 'w2 nodal refused: nodal/advanced does not read back as its W2 form';
  end if;

  raise notice 'w2 nodal: % of 2 row(s) written, % already applied', v_written, 2 - v_written;
end $$;
